package dev.DraGonFiirE.littleperformanceimprovements.client.render;
import com.mojang.blaze3d.vertex.*;import team.creative.littletiles.client.render.overlay.PreviewRenderer;import team.creative.littletiles.client.render.mc.MeshDataExtender;import team.creative.littletiles.common.math.box.collection.LittleBoxes;
public final class DefaultSphereExterior {
 public static PreviewRenderer.BoxRenderResult build(PreviewRenderer renderer,LittleBoxes boxes){var faces=DragExteriorMesh.faces(boxes);if(faces==null)return IndexedDefaultBoxMesh.build(renderer,boxes,false);var owner=renderer.createBuffer();try{var builder=renderer.createBuilder(owner,false);float scale=(float)boxes.grid.pixelLength;for(var f:faces){int axis=f[0],a=f[3],b=f[4];boolean forward=((a+1)%3==b)==(f[1]==1);for(int j=0;j<4;j++){int corner=forward?j:(4-j)%4;float u=f[corner==1||corner==2?6:5]*scale,v=f[corner>=2?8:7]*scale,h=f[2]*scale;builder.addVertex(axis==0?h:a==0?u:v,axis==1?h:a==1?u:v,axis==2?h:a==2?u:v).setColor(-1);}}var mesh=builder.build();if(mesh instanceof MeshDataExtender ext)ext.keepAlive(true);DefaultCylinderGrid2.mark(mesh);return new PreviewRenderer.BoxRenderResult(boxes,boxes.pos,owner,mesh);}catch(Throwable error){owner.close();throw error;}}
}
